package com.allthinkstars.framework.iot.ai.gateway;

import com.allthinkstars.framework.iot.ai.config.AiProperties;
import com.allthinkstars.framework.iot.ai.entity.AiBizPrincipal;
import com.allthinkstars.framework.iot.ai.mcp.context.AiContextResolveService;
import com.allthinkstars.framework.iot.ai.store.domain.AiConversationDeleteResponse;
import com.allthinkstars.framework.iot.ai.store.domain.AiConversationListItem;
import com.allthinkstars.framework.iot.ai.store.domain.AiConversationRenameRequest;
import com.allthinkstars.framework.iot.ai.store.domain.AiConversationRenameResponse;
import com.allthinkstars.framework.iot.ai.store.service.AiConversationService;
import com.allthinkstars.framework.iot.business.enums.FileUploadSourceEnum;
import com.allthinkstars.framework.iot.business.service.FileBusinessRelationService;
import com.allthinkstars.framework.iot.business.support.IotUnifiedSupport;
import com.ruoyi.common.annotation.Anonymous;
import com.ruoyi.common.core.controller.BaseController;
import com.ruoyi.common.exception.ServiceException;
import com.alibaba.fastjson.JSONArray;
import com.alibaba.fastjson.JSONObject;
import io.swagger.annotations.Api;
import io.swagger.annotations.ApiOperation;
import lombok.RequiredArgsConstructor;
import org.springframework.boot.autoconfigure.condition.ConditionalOnExpression;
import org.springframework.http.HttpHeaders;
import org.springframework.http.MediaType;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.multipart.MultipartFile;
import org.springframework.web.servlet.mvc.method.annotation.StreamingResponseBody;

import javax.servlet.http.HttpServletRequest;
import javax.validation.Valid;
import java.io.IOException;
import java.io.InputStream;
import java.util.Collections;
import java.util.List;
import java.util.Map;
import java.util.Locale;

/** iot-app 与 iot-erp 共用的用户侧 AI 会话入口，身份与当前工厂始终由所在 Java 服务解析。 */
@Api(value = "AI Gateway API", tags = {"AI Gateway"})
@RequiredArgsConstructor
@RestController
@Anonymous
@RequestMapping("/api/ai")
@ConditionalOnExpression("'${spring.application.name:}' == 'iot-app' || '${spring.application.name:}' == 'iot-erp'")
public class AiController extends BaseController {

    private final AiContextResolveService contextResolverService;
    private final AiGatewayProxyService proxyService;
    private final AiConversationService conversationGatewayService;
    private final AliyunAsrService aliyunAsrService;
    private final AiProperties aiProperties;
    private final IotUnifiedSupport iotUnifiedSupport;
    private final FileBusinessRelationService fileRelationService;

    /**
     * 前端只读取与网关鉴权相同的运行时开关；配置缺失时 AiProperties 默认返回关闭。
     */
    @ApiOperation("Get AI gateway status")
    @GetMapping("/status")
    public Map<String, Boolean> status(HttpServletRequest request) {
        if (!aiProperties.getGateway().isEnabled()) {
            return Collections.singletonMap("enabled", false);
        }
        try {
            AiBizPrincipal principal = contextResolverService.resolvePrincipal(request, aiProperties.getGateway());
            Long currentDeptId = principal.getTenantDeptId() == null
                ? null
                : Long.valueOf(principal.getTenantDeptId());
            return Collections.singletonMap(
                "enabled",
                contextResolverService.isAllowedDept(aiProperties.getGateway(), currentDeptId)
            );
        } catch (RuntimeException ignored) {
            // 未登录或无法解析当前工厂时不暴露 AI 菜单；真正的会话接口仍返回明确的鉴权错误。
            return Collections.singletonMap("enabled", false);
        }
    }

    @ApiOperation("Create AI conversation")
    @PostMapping(value = "/conversations", consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<StreamingResponseBody> createConversation(
        @RequestBody(required = false) String body,
        @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        // 这里统一声明成 StreamingResponseBody，是为了让 Spring 明确走流式返回值处理器。
        // 如果方法签名写成 ResponseEntity<?>，即使 body 实际上是 StreamingResponseBody，
        // 某些运行时也会退回到普通 HttpMessageConverter，最终把 SSE 分支错误地当成普通 JSON 序列化。
        if (acceptsEventStream(request)) {
            return proxyService.proxyCreateConversationStream(body, idempotencyKey, principal, authorization);
        }
        return proxyService.proxyCreateConversationAsStream(body, idempotencyKey, principal, authorization);
    }

    @ApiOperation("Create AI conversation with images")
    @PostMapping(value = "/conversations", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<StreamingResponseBody> createConversationWithImages(
        @RequestParam(value = "query", required = false) String query,
        @RequestParam(value = "images", required = false) List<MultipartFile> images,
        @RequestParam(value = "files", required = false) List<MultipartFile> files,
        @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        // PDF 在进入 Agent 前先上传 OSS，查询文本携带可信 fileId，后续 confirm 可直接关联原始文件。
        String forwardedQuery = appendSourceFiles(query, files, principal);
        if (acceptsEventStream(request)) {
            return proxyService.proxyCreateConversationMultipartStream(
                forwardedQuery, images, files, idempotencyKey, principal, authorization
            );
        }
        return proxyService.proxyCreateConversationMultipartAsStream(
            forwardedQuery, images, files, idempotencyKey, principal, authorization
        );
    }

    @ApiOperation("Chat with AI conversation")
    @PostMapping(value = "/conversations/{conversationId}/chat", consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<StreamingResponseBody> chatConversation(
        @PathVariable("conversationId") String conversationId,
        @RequestBody(required = false) String body,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        if (acceptsEventStream(request)) {
            return proxyService.proxyChatStream(conversationId, body, principal, authorization);
        }
        return proxyService.proxyChatAsStream(conversationId, body, principal, authorization);
    }

    @ApiOperation("Chat with AI conversation and images")
    @PostMapping(value = "/conversations/{conversationId}/chat", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<StreamingResponseBody> chatConversationWithImages(
        @PathVariable("conversationId") String conversationId,
        @RequestParam(value = "query", required = false) String query,
        @RequestParam(value = "images", required = false) List<MultipartFile> images,
        @RequestParam(value = "files", required = false) List<MultipartFile> files,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        // 续聊上传的 PDF 与新会话保持同一登记口径，避免模型拿到无法回填的临时路径。
        String forwardedQuery = appendSourceFiles(query, files, principal);
        if (acceptsEventStream(request)) {
            return proxyService.proxyChatMultipartStream(
                conversationId, forwardedQuery, images, files, principal, authorization
            );
        }
        return proxyService.proxyChatMultipartAsStream(
            conversationId, forwardedQuery, images, files, principal, authorization
        );
    }

    @ApiOperation("Transcribe a recorded audio clip to editable text")
    @PostMapping(value = "/asr/transcriptions", consumes = MediaType.MULTIPART_FORM_DATA_VALUE, produces = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<Map<String, String>> transcribeAudio(
        @RequestParam(value = "audio", required = false) MultipartFile audio,
        HttpServletRequest request
    ) {
