    /**
     * 仅允许 PDF 进入单据识别链路，并把服务端生成的 fileId 追加为结构化上下文。
     */
    private String appendSourceFiles(String query, List<MultipartFile> files, AiBizPrincipal principal) {
        if (files == null || files.isEmpty()) {
            return query;
        }
        Long tenantId;
        try {
            tenantId = Long.valueOf(principal.getTenantDeptId());
        } catch (RuntimeException e) {
            throw new ServiceException("当前工厂上下文无效");
        }

        JSONArray metadata = new JSONArray();
        for (MultipartFile file : files) {
            if (!isPdf(file)) {
                throw new ServiceException("单据附件仅支持非空 PDF 文件");
            }
        }

        // 全部文件通过类型校验后再上传，避免批量请求中途失败留下部分临时附件。
        for (MultipartFile file : files) {
            IotUnifiedSupport.UploadFileResult uploaded = iotUnifiedSupport.uploadFileAndResult(file);
            fileRelationService.saveRelation(tenantId, uploaded.getFileId(), uploaded.getFileUrl(),
                uploaded.getOriginalFilename(), FileUploadSourceEnum.AI_DOCUMENT_IMPORT.getCode(), null, null);
            JSONObject item = new JSONObject();
            item.put("sourceFileId", uploaded.getFileId());
            item.put("originalFilename", uploaded.getOriginalFilename());
            metadata.add(item);
        }
        return "[ERP_SOURCE_FILES]" + metadata.toJSONString() + "\n" + String.valueOf(query == null ? "" : query);
    }

    /**
     * 同时校验扩展名和文件头，避免只伪造 Content-Type 的非 PDF 文件进入识别与归档链路。
     */
    private boolean isPdf(MultipartFile file) {
        String filename = file == null ? null : file.getOriginalFilename();
        if (file == null || file.isEmpty()
            || !String.valueOf(filename).toLowerCase(Locale.ROOT).endsWith(".pdf")) {
            return false;
        }
        try (InputStream input = file.getInputStream()) {
            byte[] header = new byte[1024];
            int length = input.read(header);
            return length > 0 && new String(header, 0, length, java.nio.charset.StandardCharsets.ISO_8859_1)
                .contains("%PDF-");
        } catch (IOException e) {
            throw new ServiceException("读取PDF文件失败", e);
        }
    }

    private boolean acceptsEventStream(HttpServletRequest request) {
        String outputMode = normalizeOutputMode(aiProperties.getGateway().getOutputMode());
        if ("sse".equals(outputMode)) {
            return true;
        }
        if ("block".equals(outputMode)) {
            return false;
        }
        if (request == null) {
            return false;
        }
        String accept = request.getHeader("Accept");
        if (accept == null) {
            return false;
        }
        return accept.toLowerCase().contains(MediaType.TEXT_EVENT_STREAM_VALUE);
    }

    private String normalizeOutputMode(String raw) {
        if (raw == null) {
            return "auto";
        }
        String normalized = raw.trim().toLowerCase();
        if ("sse".equals(normalized) || "block".equals(normalized)) {
            return normalized;
        }
        return "auto";
    }
