    /**
     * 前端只读取与网关鉴权相同的运行时开关；配置缺失时 AiProperties 默认返回关闭。
     */
    @ApiOperation("Get AI gateway status")
    @GetMapping("/status")
    public Map<String, Boolean> status(HttpServletRequest request) {
        if (!aiProperties.getGateway().isEnabled()) {
            return Collections.singletonMap("enabled", false);
        }
        try {
            AiBizPrincipal principal = contextResolverService.resolvePrincipal(request, aiProperties.getGateway());
            Long currentDeptId = principal.getTenantDeptId() == null
                ? null
                : Long.valueOf(principal.getTenantDeptId());
            return Collections.singletonMap(
                "enabled",
                contextResolverService.isAllowedDept(aiProperties.getGateway(), currentDeptId)
            );
        } catch (RuntimeException ignored) {
            // 未登录或无法解析当前工厂时不暴露 AI 菜单；真正的会话接口仍返回明确的鉴权错误。
            return Collections.singletonMap("enabled", false);
        }
    }

    @ApiOperation("Create AI conversation")
    @PostMapping(value = "/conversations", consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<StreamingResponseBody> createConversation(
        @RequestBody(required = false) String body,
        @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        // 这里统一声明成 StreamingResponseBody，是为了让 Spring 明确走流式返回值处理器。
        // 如果方法签名写成 ResponseEntity<?>，即使 body 实际上是 StreamingResponseBody，
        // 某些运行时也会退回到普通 HttpMessageConverter，最终把 SSE 分支错误地当成普通 JSON 序列化。
        if (acceptsEventStream(request)) {
            return proxyService.proxyCreateConversationStream(body, idempotencyKey, principal, authorization);
        }
        return proxyService.proxyCreateConversationAsStream(body, idempotencyKey, principal, authorization);
    }

    @ApiOperation("Create AI conversation with images")
    @PostMapping(value = "/conversations", consumes = MediaType.MULTIPART_FORM_DATA_VALUE)
    public ResponseEntity<StreamingResponseBody> createConversationWithImages(
        @RequestParam(value = "query", required = false) String query,
        @RequestParam(value = "images", required = false) List<MultipartFile> images,
        @RequestParam(value = "files", required = false) List<MultipartFile> files,
        @RequestHeader(value = "Idempotency-Key", required = false) String idempotencyKey,
        HttpServletRequest request
    ) {
        AiBizPrincipal principal = resolvePrincipal(request);
        String authorization = request.getHeader(HttpHeaders.AUTHORIZATION);
        // PDF 在进入 Agent 前先上传 OSS，查询文本携带可信 fileId，后续 confirm 可直接关联原始文件。
        String forwardedQuery = appendSourceFiles(query, files, principal);
        if (acceptsEventStream(request)) {
            return proxyService.proxyCreateConversationMultipartStream(
                forwardedQuery, images, files, idempotencyKey, principal, authorization
            );
        }
        return proxyService.proxyCreateConversationMultipartAsStream(
            forwardedQuery, images, files, idempotencyKey, principal, authorization
        );
    }

    @ApiOperation("Chat with AI conversation")
    @PostMapping(value = "/conversations/{conversationId}/chat", consumes = MediaType.APPLICATION_JSON_VALUE)
    public ResponseEntity<StreamingResponseBody> chatConversation(
        @PathVariable("conversationId") String conversationId,
