            builder.contentType(mediaType);
        }
        return builder.body(body == null ? "" : body);
    }

    private ResponseEntity<StreamingResponseBody> toStreamingResponse(ResponseEntity<String> response) {
        // create/chat 的 Controller 统一走 StreamingResponseBody，Spring 才会稳定套用流式返回处理器。
        // block 模式仍然需要保持原有状态码、Content-Type 与响应体，所以这里把 JSON 响应包装成一次性写出的流，
        // 避免 ResponseEntity<?> 在运行时被当成普通对象走 HttpMessageConverter，进而触发 SSE 分支 500。
        HttpHeaders headers = new HttpHeaders();
        headers.putAll(response.getHeaders());
        StreamingResponseBody body = outputStream -> {
            byte[] bytes = defaultText(response.getBody(), "").getBytes(StandardCharsets.UTF_8);
            if (bytes.length > 0) {
                outputStream.write(bytes);
            }
            outputStream.flush();
        };
        return ResponseEntity.status(response.getStatusCode()).headers(headers).body(body);
    }

    private InputStream openResponseStream(HttpURLConnection conn, int statusCode) throws IOException {
        return statusCode >= 400 ? conn.getErrorStream() : conn.getInputStream();
    }

    private MediaType parseMediaType(String contentType) {
        if (contentType == null || contentType.isBlank()) {
            return null;
        }
        try {
            return MediaType.parseMediaType(contentType);
        } catch (Exception ignored) { // NOSONAR
            return null;
        }
    }

    private String normalizeBaseUrl(String raw) {
        String base = safeText(raw);
        if (base.isEmpty()) {
            throw new IllegalStateException("ai.gateway.pythonBaseUrl is required");
        }
        while (base.endsWith("/")) {
            base = base.substring(0, base.length() - 1);
        }
        return base;
    }

    private String normalizeBody(String body) {
        if (body == null || body.isBlank()) {
            return "{}";
        }
        return body;
    }

    private String urlEncode(String value) {
        try {
            return URLEncoder.encode(value, StandardCharsets.UTF_8.name());
        } catch (Exception e) { // NOSONAR
            throw new IllegalStateException("url encode failed", e);
        }
    }

    private String safeText(String text) {
        return text == null ? "" : text.trim();
    }

