import com.allthinkstars.framework.iot.ai.mcp.api.*;
import com.allthinkstars.framework.iot.business.support.IotCommonSupport;
import com.allthinkstars.framework.iot.nextg.entity.TbDeviceFurnace;
import com.allthinkstars.framework.iot.nextg.mapper.TbDeviceFurnaceMapper;
import com.allthinkstars.framework.iot.nextg.service.UnifiedUserDeptService;
import com.ruoyi.common.core.domain.entity.SysDept;
import com.ruoyi.common.core.domain.model.LoginUser;
import com.ruoyi.common.helper.LoginHelper;
import com.ruoyi.system.mapper.SysDeptMapper;
import lombok.RequiredArgsConstructor;
import org.apache.commons.lang3.StringUtils;
import org.springframework.http.HttpStatus;
import org.springframework.web.server.ResponseStatusException;

import javax.servlet.http.HttpServletRequest;
import java.util.*;
import java.util.stream.Collectors;

@RequiredArgsConstructor
public class AiContextResolveService {

    private static final String SNAPSHOT_VERSION = "v2";
    private static final String HEADER_TRACE_ID = "X-Trace-Id";

    private final IotCommonSupport iotCommonSupport;
    private final UnifiedUserDeptService userDeptService;
    private final SysDeptMapper sysDeptMapper;
    private final TbDeviceFurnaceMapper tbDeviceFurnaceMapper;

    /**
     * 统一网关身份解析入口：
     * - userId 沿用 Sa-Token 当前线程登录态
     * - deptId 统一走 UnifiedUserDeptService
     */
    public AiBizPrincipal resolvePrincipal(HttpServletRequest request, AiProperties.Gateway gateway) {
        if (!gateway.isEnabled()) {
            throw new ResponseStatusException(HttpStatus.FORBIDDEN, "ai gateway disabled");
        }
        String traceId = resolveTraceId(request);
        try {
            LoginUser loginUser = LoginHelper.getLoginUser();
            Long userId = loginUser == null ? null : loginUser.getUserId();
            Long deptId = userDeptService.getCurrentDeptId();
            if (userId == null || deptId == null) {
                throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "unauthenticated");
            }
            if (!isAllowedDept(gateway, deptId)) {
                throw new ResponseStatusException(HttpStatus.FORBIDDEN, "ai gateway unavailable for current factory");
            }
            return new AiBizPrincipal(
                String.valueOf(userId),
                String.valueOf(deptId),
                traceId,
                resolveAiUserType(loginUser),
                resolvePrincipalVisibleFurnaces(deptId)
            );
        } catch (ResponseStatusException ex) {
            throw ex;
        } catch (Exception ignored) { // NOSONAR
            throw new ResponseStatusException(HttpStatus.UNAUTHORIZED, "unauthenticated");
        }
    }

    /**
     * 工厂白名单在 Java 入口校验，避免只依赖前端隐藏菜单；即使客户手工调用接口也会被拒绝。
     */
    public boolean isAllowedDept(AiProperties.Gateway gateway, Long deptId) {
        return deptId != null
            && (gateway.getAllowedDeptIds() == null
                || gateway.getAllowedDeptIds().isEmpty()
                || gateway.getAllowedDeptIds().contains(deptId));
    }

    /**
     * AI 网关不向下游暴露完整角色集合，只收口成稳定 userType。
     * 当前 admin 覆盖系统管理员/调试管理员两类内部运维角色，其余统一视为普通用户。
     */
    private AiUserType resolveAiUserType(LoginUser loginUser) {
        if (loginUser == null) {
            return AiUserType.USER;
        }
        boolean isAdminRole = loginUser.getRolePermission() != null
            && loginUser.getRolePermission().stream()
            .filter(Objects::nonNull)
            .map(String::trim)
            .anyMatch("admin"::equals);
        boolean hasDebugPrivilege = loginUser.getDebugPrivilege() != null && loginUser.getDebugPrivilege() == 1;
        return isAdminRole || hasDebugPrivilege ? AiUserType.ADMIN : AiUserType.USER;
    }

    /**
     * 将“租户+用户”解析为调用时可见范围快照
     * 快照是“当前时刻”的结果，不保证跨时刻一致（权限变更会影响）
     */
    public AiMcpContextResolveResponse resolve(AiMcpContextResolveRequest req) {
        AiMcpContextResolveResponse resp = new AiMcpContextResolveResponse();
        SysDept currentFactory = resolveCurrentFactory(req.getTenantDeptId());
        List<Long> visibleDeviceIds = resolveVisibleDeviceIds(req.getTenantDeptId(), req.getUserId());
        resp.setTenantDeptId(req.getTenantDeptId());
        resp.setUserId(req.getUserId());
        resp.setTenantId(req.getTenantId());
        resp.setVisibleDeviceInternalIds(visibleDeviceIds);
        resp.setVisibleDeptIds(resolveVisibleDeptIds(currentFactory, req.getTenantDeptId()));
        resp.setCurrentFactory(toCurrentFactorySnapshot(currentFactory));
        resp.setVisibleFurnaces(resolveVisibleFurnaces(visibleDeviceIds, currentFactory));
        resp.setPermissions(buildPermissionSnapshot());
        resp.setResolvedAt(System.currentTimeMillis());
        resp.setVersion(SNAPSHOT_VERSION);
        return resp;
    }

    /**
     * caller 版本的便捷重载，给 dispatcher 做按需补全用
     */
    public AiMcpContextResolveResponse resolve(AiMcpCallerContext callerContext) {
        AiMcpContextResolveRequest req = new AiMcpContextResolveRequest();
        req.setTenantDeptId(parseTenantDeptId(callerContext.getTenantId()));
        req.setUserId(callerContext.getUserId());
        req.setTenantId(callerContext.getTenantId());
        return resolve(req);
    }

    /**
     * 网关转发时按 principal 生成最小 conversationContext，避免重复组装请求对象
     */
    public AiMcpContextResolveResponse resolve(AiBizPrincipal principal) {
        AiMcpContextResolveRequest req = new AiMcpContextResolveRequest();
        req.setTenantId(principal.getTenantDeptId());
        req.setTenantDeptId(parseTenantDeptId(principal.getTenantDeptId()));
        req.setUserId(parseUserId(principal.getUserId()));
        return resolve(req);
    }

    /**
     * conversation planner 最小上下文：
     * - userId
     * - tenantDeptId
     * - deptName
     * - furnaces[].fnCode
     */
    public AiConversationContext resolveConversationContext(AiBizPrincipal principal) {
        AiConversationContext context = new AiConversationContext();
        context.setUserId(principal.getUserId());
        context.setTenantDeptId(principal.getTenantDeptId());
        context.setDeptName(resolveConversationDeptName(principal));
        context.setFurnaces(resolveConversationFurnaces(principal));
        return context;
    }

    /**
     * 当前工厂名称是“用户当前在哪个工厂下”这类问题的直接证据。
     * 这里统一复用当前工厂解析逻辑，保证 Java 网关和 MCP 解析对工厂口径保持一致。
     */
    private String resolveConversationDeptName(AiBizPrincipal principal) {
        if (principal == null) {
            return null;
        }
        SysDept currentFactory = resolveCurrentFactory(parseTenantDeptId(principal.getTenantDeptId()));
        return currentFactory == null ? null : safeText(currentFactory.getDeptName(), null);
    }

    private Long parseTenantDeptId(String tenantId) {
        if (tenantId == null || tenantId.isBlank()) {
            throw new IllegalArgumentException("tenantId不能为空");
        }
        try {
            return Long.parseLong(tenantId.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("tenantId必须是数字", e);
        }
    }

    private Long parseUserId(String userId) {
        if (userId == null || userId.isBlank()) {
            throw new IllegalArgumentException("userId不能为空");
        }
        try {
            return Long.parseLong(userId.trim());
        } catch (NumberFormatException e) {
            throw new IllegalArgumentException("userId必须是数字", e);
        }
    }

    /**
     * 设备可见范围查询：
     * - 通过 IotCommonSupport 查权限关联设备
     * - 去重并保持顺序，避免重复 DID 影响下游查询效率
     */
    private List<Long> resolveVisibleDeviceIds(Long tenantDeptId, Long userId) {
        List<Long> visibleDeviceIds = iotCommonSupport.getRelatedDeviceInternalIdList(tenantDeptId, userId);
        if (visibleDeviceIds == null || visibleDeviceIds.isEmpty()) {
            return Collections.emptyList();
        }
        Set<Long> deduplicated = new LinkedHashSet<>(visibleDeviceIds);
        return new ArrayList<>(deduplicated);
    }

    /**
     * 当前实现将租户部门作为最小可见部门集合
     * 后续若引入多级组织权限，可在此扩展
     */
    private List<Long> resolveVisibleDeptIds(SysDept currentFactory, Long tenantDeptId) {
        Long currentFactoryDeptId = currentFactory == null ? tenantDeptId : currentFactory.getDeptId();
        if (currentFactoryDeptId == null) {
            return Collections.emptyList();
        }
        return Collections.singletonList(currentFactoryDeptId);
    }

    /**
     * 网关给 planner 注入的炉体列表需要和当前登录体系保持一致
     * 这里直接复用 UnifiedUserDeptService 的“当前用户可见炉体”能力，
     * 避免 ERP 场景继续走旧 relation 表导致默认设备下的炉体全部丢失
     */
    private List<AiBizVisibleFurnace> resolvePrincipalVisibleFurnaces(Long tenantDeptId) {
        SysDept currentFactory = resolveCurrentFactory(tenantDeptId);
        List<AiMcpFurnaceSnapshot> visibleFurnaces = resolveVisibleFurnacesFromEntities(
            userDeptService.getUserVisibleDeviceFurnaces(),
            currentFactory
        );
        if (visibleFurnaces.isEmpty()) {
            return Collections.emptyList();
        }
        return visibleFurnaces.stream()
            .map(this::toBizVisibleFurnace)
            .filter(Objects::nonNull)
            .collect(Collectors.toList());
    }

    private List<AiConversationContextFurnace> resolveConversationFurnaces(AiBizPrincipal principal) {
        if (principal == null || principal.getVisibleFurnaces() == null || principal.getVisibleFurnaces().isEmpty()) {
            return Collections.emptyList();
        }
        LinkedHashSet<String> seen = new LinkedHashSet<>();
        List<AiConversationContextFurnace> result = new ArrayList<>();
        for (AiBizVisibleFurnace furnace : principal.getVisibleFurnaces()) {
            if (furnace == null) {
                continue;
            }
            String fnCode = safeText(furnace.getFnCode(), null);
            if (fnCode == null || !seen.add(fnCode)) {
                continue;
            }
            result.add(new AiConversationContextFurnace(fnCode));
        }
        return result;
    }

    private SysDept resolveCurrentFactory(Long tenantDeptId) {
        if (tenantDeptId == null) {
            return null;
        }
        return sysDeptMapper.selectFactoryDeptByDeptId(tenantDeptId);
    }

    private AiMcpCurrentFactorySnapshot toCurrentFactorySnapshot(SysDept currentFactory) {
        if (currentFactory == null) {
            return null;
        }
        AiMcpCurrentFactorySnapshot snapshot = new AiMcpCurrentFactorySnapshot();
        snapshot.setDeptId(currentFactory.getDeptId());
        snapshot.setDeptName(currentFactory.getDeptName());
        snapshot.setDeptSimpleName(currentFactory.getDeptSimpleName());
        snapshot.setDeptNameAbbreviationEn(currentFactory.getDeptNameAbbreviationEn());
        snapshot.setStatus(currentFactory.getStatus());
        return snapshot;
    }

    private List<AiMcpFurnaceSnapshot> resolveVisibleFurnaces(List<Long> visibleDeviceIds, SysDept currentFactory) {
        if (visibleDeviceIds == null || visibleDeviceIds.isEmpty()) {
            return Collections.emptyList();
        }
        return resolveVisibleFurnacesFromEntities(tbDeviceFurnaceMapper.selectListByDidList(visibleDeviceIds), currentFactory);
    }

    /**
     * principal 路径已经拿到了统一口径的炉体列表，后续只保留当前工厂内的炉体并稳定排序
     */
    private List<AiMcpFurnaceSnapshot> resolveVisibleFurnacesFromEntities(List<TbDeviceFurnace> visibleFurnaces,
                                                                          SysDept currentFactory) {
        if (visibleFurnaces == null || visibleFurnaces.isEmpty()) {
