package com.allthinkstars.framework.iot.ai.config;

import com.alibaba.nacos.api.config.annotation.NacosValue;
import lombok.Data;
import org.springframework.boot.context.properties.ConfigurationProperties;

import java.util.Collections;
import java.util.List;

@Data
@ConfigurationProperties(prefix = "ai")
public class AiProperties {
    private Mcp mcp = new Mcp();
    private Gateway gateway = new Gateway();

    /**
     * Nacos 变更时把唯一的 AI 网关开关同步到现有配置对象，入口展示与接口访问据此保持一致。
     */
    @NacosValue(value = "${ai.gateway.enabled:false}", autoRefreshed = true)
    public void refreshGatewayEnabled(boolean enabled) {
        this.gateway.setEnabled(enabled);
    }

    @Data
    public static class Mcp {
        /**
         * MCP internal APIs switch.
         */
        private boolean enabled = false;

        /**
         * Lightweight internal auth token for MCP internal APIs.
         */
        private String internalToken = "";
    }

    @Data
    public static class Gateway {
        /**
         * Java AI gateway switch (front-end -> Java -> Python).
         */
        private boolean enabled = false;

        /**
         * Python AI service base URL, e.g. http://127.0.0.1:8000
         */
        private String pythonBaseUrl = "http://127.0.0.1:8000";

        /**
         * Shared lightweight internal token for Java -> Python gateway calls.
         */
        private String internalToken = "";

        /**
         * HMAC secret for X-AI-BIZ-CONTEXT signing.
         */
        private String contextSignSecret = "";

        /**
         * Signed context ttl in seconds.
         */
        private long contextTtlSeconds = 300;

        private int connectTimeoutMs = 5000;

        private int readTimeoutMs = 65000;

        /**
         * Output mode for create/chat endpoints: auto | sse | block.
         * auto keeps content negotiation by Accept header.
         */
        private String outputMode = "auto";

        /**
         * 允许使用数字员工的 ERP 工厂部门 ID。
         * 空列表表示不限制（仅适合开发环境）；生产必须显式配置，避免新客户默认获得 AI 入口。
         */
        private List<Long> allowedDeptIds = Collections.emptyList();
    }
}
