                    output.flush();
                }
            }
            int status = conn.getResponseCode();
            String body = readBody(conn);
            return buildResponse(status, conn.getHeaderField(HttpHeaders.CONTENT_TYPE), body);
        } catch (IOException e) {
            LOG.error("proxy request failed method={} path={}", method, path, e);
            return ResponseEntity.status(502)
                .contentType(MediaType.APPLICATION_JSON)
                .body("{\"detail\":\"proxy ai service failed\"}");
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private ResponseEntity<String> proxyJsonWithoutBody(String method,
                                                        String path,
                                                        AiBizPrincipal principal,
                                                        boolean includeResolvedContext) {
        HttpURLConnection conn = null;
        try {
            conn = openConnection(method, path);
            conn.setRequestProperty(HttpHeaders.ACCEPT, MediaType.APPLICATION_JSON_VALUE);
            applyGatewayHeaders(conn, principal, includeResolvedContext);
            int status = conn.getResponseCode();
            String body = readBody(conn);
            return buildResponse(status, conn.getHeaderField(HttpHeaders.CONTENT_TYPE), body);
        } catch (IOException e) {
            LOG.error("proxy request failed method={} path={}", method, path, e);
            return ResponseEntity.status(502)
                .contentType(MediaType.APPLICATION_JSON)
                .body("{\"detail\":\"proxy ai service failed\"}");
        } finally {
            if (conn != null) {
                conn.disconnect();
            }
        }
    }

    private HttpURLConnection openConnection(String method, String path) throws IOException {
        AiProperties.Gateway gateway = aiProperties.getGateway();
        String baseUrl = normalizeBaseUrl(gateway.getPythonBaseUrl());
        URL url = new URL(baseUrl + path);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod(method);
        conn.setConnectTimeout(gateway.getConnectTimeoutMs());
        conn.setReadTimeout(gateway.getReadTimeoutMs());
        conn.setUseCaches(false);
        conn.setDoInput(true);
        return conn;
    }

    private void applyGatewayHeaders(HttpURLConnection conn, AiBizPrincipal principal, boolean includeResolvedContext) {
        AiProperties.Gateway gateway = aiProperties.getGateway();
        conn.setRequestProperty(HEADER_GATEWAY_TOKEN, safeText(gateway.getInternalToken()));
        conn.setRequestProperty(HEADER_BIZ_CONTEXT, buildSignedBizContext(principal, includeResolvedContext));
        conn.setRequestProperty(HEADER_TRACE_ID, principal.getTraceId());
    }

    private void applyAuthorization(HttpURLConnection conn, String authorization) {
        String safeAuthorization = safeText(authorization);
        if (safeAuthorization.isEmpty()) {
            return;
        }
        if (safeAuthorization.indexOf('\r') >= 0 || safeAuthorization.indexOf('\n') >= 0) {
            throw new IllegalArgumentException("Authorization header非法");
        }
        // 用户 Token 只作为本次 Gateway -> Pi 请求头透传，不写入签名业务上下文、请求体或消息记录。
        conn.setRequestProperty(HttpHeaders.AUTHORIZATION, safeAuthorization);
    }

    private String buildSignedBizContext(AiBizPrincipal principal, boolean includeResolvedContext) {
        AiProperties.Gateway gateway = aiProperties.getGateway();
        String secret = safeText(gateway.getContextSignSecret());
        if (secret.isEmpty()) {
            throw new IllegalStateException("ai.gateway.contextSignSecret is required");
        }
        long now = Instant.now().getEpochSecond();
        long ttl = Math.max(30L, gateway.getContextTtlSeconds());

        Map<String, Object> payload = new LinkedHashMap<>();
        payload.put("v", 1);
        payload.put("userId", principal.getUserId());
        payload.put("tenantDeptId", principal.getTenantDeptId());
        payload.put("tenantId", principal.getTenantDeptId());
        payload.put("traceId", principal.getTraceId());
        payload.put("userType", principal.getUserType() == null ? "user" : principal.getUserType().getCode());
        if (includeResolvedContext) {
            payload.put("conversationContext", resolveConversationContext(principal));
        }
        payload.put("iat", now);
        payload.put("exp", now + ttl);

        String payloadJson;
        try {
            payloadJson = objectMapper.writeValueAsString(payload);
        } catch (JsonProcessingException e) {
            throw new IllegalStateException("serialize biz context failed", e);
        }
        String payloadB64 = Base64.getUrlEncoder().withoutPadding()
            .encodeToString(payloadJson.getBytes(StandardCharsets.UTF_8));
        String signatureB64 = hmacSha256Base64Url(secret, payloadB64);
        return "v1." + payloadB64 + "." + signatureB64;
    }

    private Object resolveConversationContext(AiBizPrincipal principal) {
        AiConversationContext context = contextResolverService.resolveConversationContext(principal);
        return context;
    }

    private String defaultText(String value, String fallback) {
        if (value == null || value.isBlank()) {
            return fallback;
        }
        return value.trim();
    }

    private String hmacSha256Base64Url(String secret, String payload) {
        try {
            Mac mac = Mac.getInstance("HmacSHA256");
            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
            byte[] digest = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
            return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);
        } catch (Exception e) { // NOSONAR
            throw new IllegalStateException("sign biz context failed", e);
        }
    }

    private String readBody(HttpURLConnection conn) throws IOException {
        InputStream stream = openResponseStream(conn, conn.getResponseCode());
        if (stream == null) {
            return "";
        }
        try (InputStream in = stream; ByteArrayOutputStream out = new ByteArrayOutputStream()) {
            byte[] buffer = new byte[IO_BUFFER_SIZE];
            int read;
            while ((read = in.read(buffer)) != -1) {
                out.write(buffer, 0, read);
            }
            return out.toString(StandardCharsets.UTF_8.name());
        }
    }

    private ResponseEntity<String> buildResponse(int status, String contentType, String body) {
        ResponseEntity.BodyBuilder builder = ResponseEntity.status(status);
        MediaType mediaType = parseMediaType(contentType);
        if (mediaType != null) {
            builder.contentType(mediaType);
        }
        return builder.body(body == null ? "" : body);
    }

    private ResponseEntity<StreamingResponseBody> toStreamingResponse(ResponseEntity<String> response) {
        // create/chat 的 Controller 统一走 StreamingResponseBody，Spring 才会稳定套用流式返回处理器。
        // block 模式仍然需要保持原有状态码、Content-Type 与响应体，所以这里把 JSON 响应包装成一次性写出的流，
        // 避免 ResponseEntity<?> 在运行时被当成普通对象走 HttpMessageConverter，进而触发 SSE 分支 500。
        HttpHeaders headers = new HttpHeaders();
        headers.putAll(response.getHeaders());
        StreamingResponseBody body = outputStream -> {
            byte[] bytes = defaultText(response.getBody(), "").getBytes(StandardCharsets.UTF_8);
            if (bytes.length > 0) {
                outputStream.write(bytes);
