337			const presentationCatalog = this.javaMcp.getPresentationCatalog(customTools);
338			const previousCatalog = lastToolPresentationCatalog(sessionManager.getEntries());
339			if (JSON.stringify(previousCatalog) !== JSON.stringify(presentationCatalog)) {
