353				cwd: this.config.workingDirectory,
354				modelRuntime: this.modelRuntime,
355				model: this.model,
356				sessionManager,
357				resourceLoader,
358				customTools,
359				noTools: "builtin",
360			});
361			return { session, sessionManager, presentations: presentationCatalog };
362		}
