547	    private void applyAuthorization(HttpURLConnection conn, String authorization) {
548	        String safeAuthorization = safeText(authorization);
549	        if (safeAuthorization.isEmpty()) {
550	            return;
551	        }
552	        if (safeAuthorization.indexOf('\r') >= 0 || safeAuthorization.indexOf('\n') >= 0) {
553	            throw new IllegalArgumentException("Authorization header非法");
554	        }
555	        // 用户 Token 只作为本次 Gateway -> Pi 请求头透传，不写入签名业务上下文、请求体或消息记录。
556	        conn.setRequestProperty(HttpHeaders.AUTHORIZATION, safeAuthorization);
557	    }
