316		private async openSession(
317			conversationId: string,
318			caller: JavaMcpCallerContext,
319			create: boolean,
320			businessContext?: ConversationBusinessContext,
321		): Promise<OpenedConversationSession> {
322			const sessionManager = create
323				? SessionManager.create(this.config.workingDirectory, this.config.sessionDirectory, { id: conversationId })
324				: await this.openExistingSession(conversationId, caller);
325			if (create) {
326				// 调用人范围用于续聊鉴权；业务上下文单独持久化，用于新会话和容器恢复后的语义一致性。
327				sessionManager.appendCustomEntry("java_gateway_context", caller);
328				if (businessContext) {
329					if (businessContext.userId !== caller.userId || businessContext.tenantDeptId !== caller.tenantId) {
330						throw new ConversationAccessDeniedError();
331					}
332					sessionManager.appendCustomEntry(BUSINESS_CONTEXT_ENTRY, businessContext);
333				}
334			}
335			const persistedBusinessContext = lastConversationBusinessContext(sessionManager.getEntries());
336			const customTools = await this.javaMcp.createTools({ conversationId, caller });
337			const presentationCatalog = this.javaMcp.getPresentationCatalog(customTools);
338			const previousCatalog = lastToolPresentationCatalog(sessionManager.getEntries());
339			if (JSON.stringify(previousCatalog) !== JSON.stringify(presentationCatalog)) {
340				// 会话历史只保存业务展示文案，Tool schema、调用参数和结果继续留在原生 Tool Entry 中。
341				sessionManager.appendCustomEntry(TOOL_PRESENTATION_ENTRY, presentationCatalog);
342			}
343			const resourceLoader = new DefaultResourceLoader({
344				cwd: this.config.workingDirectory,
345				agentDir: getAgentDir(),
346				noContextFiles: true,
347				appendSystemPrompt: persistedBusinessContext
348					? [conversationBusinessContextPrompt(persistedBusinessContext)]
349					: undefined,
350			});
351			await resourceLoader.reload();
352			const { session } = await createAgentSession({
353				cwd: this.config.workingDirectory,
354				modelRuntime: this.modelRuntime,
355				model: this.model,
356				sessionManager,
357				resourceLoader,
358				customTools,
359				noTools: "builtin",
360			});
361			return { session, sessionManager, presentations: presentationCatalog };
362		}
