559	    private String buildSignedBizContext(AiBizPrincipal principal, boolean includeResolvedContext) {
560	        AiProperties.Gateway gateway = aiProperties.getGateway();
561	        String secret = safeText(gateway.getContextSignSecret());
562	        if (secret.isEmpty()) {
563	            throw new IllegalStateException("ai.gateway.contextSignSecret is required");
564	        }
565	        long now = Instant.now().getEpochSecond();
566	        long ttl = Math.max(30L, gateway.getContextTtlSeconds());
567	
568	        Map<String, Object> payload = new LinkedHashMap<>();
569	        payload.put("v", 1);
570	        payload.put("userId", principal.getUserId());
571	        payload.put("tenantDeptId", principal.getTenantDeptId());
572	        payload.put("tenantId", principal.getTenantDeptId());
573	        payload.put("traceId", principal.getTraceId());
574	        payload.put("userType", principal.getUserType() == null ? "user" : principal.getUserType().getCode());
575	        if (includeResolvedContext) {
576	            payload.put("conversationContext", resolveConversationContext(principal));
577	        }
578	        payload.put("iat", now);
579	        payload.put("exp", now + ttl);
580	
581	        String payloadJson;
582	        try {
583	            payloadJson = objectMapper.writeValueAsString(payload);
584	        } catch (JsonProcessingException e) {
585	            throw new IllegalStateException("serialize biz context failed", e);
586	        }
587	        String payloadB64 = Base64.getUrlEncoder().withoutPadding()
588	            .encodeToString(payloadJson.getBytes(StandardCharsets.UTF_8));
589	        String signatureB64 = hmacSha256Base64Url(secret, payloadB64);
590	        return "v1." + payloadB64 + "." + signatureB64;
591	    }
