605	    private String hmacSha256Base64Url(String secret, String payload) {
606	        try {
607	            Mac mac = Mac.getInstance("HmacSHA256");
608	            mac.init(new SecretKeySpec(secret.getBytes(StandardCharsets.UTF_8), "HmacSHA256"));
609	            byte[] digest = mac.doFinal(payload.getBytes(StandardCharsets.UTF_8));
610	            return Base64.getUrlEncoder().withoutPadding().encodeToString(digest);

