package com.allthinkstars.framework.iot.ai.tools;

import com.allthinkstars.framework.iot.ai.tools.support.AiRunContext;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolDef;
import com.allthinkstars.framework.iot.ai.tools.support.annotation.AiToolParam;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ArrayNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import io.swagger.annotations.ApiOperation;
import io.swagger.annotations.ApiParam;
import lombok.extern.slf4j.Slf4j;
import org.apache.commons.lang3.StringUtils;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.ValueConstants;

import javax.validation.constraints.NotBlank;
import javax.validation.constraints.NotEmpty;
import javax.validation.constraints.NotNull;
import java.lang.reflect.InvocationTargetException;
import java.lang.reflect.Method;
import java.lang.reflect.Parameter;
import java.util.*;

@Slf4j
public class ToolRegistry {

    private final Map<String, ToolMethod> methods = new LinkedHashMap<>();
    private final Map<String, ToolSpec> specs = new LinkedHashMap<>();

    /**
     * 扫描并注册注解式工具方法
     * 注册时会一次性构建：
     * - 可执行方法描述(ToolMethod)
     * - 对外暴露的工具元信息(ToolSpec)
     */
    public void registerAnnotatedBean(ObjectMapper objectMapper, Object toolBean) {
        if (toolBean == null || objectMapper == null) {
            return;
        }
        for (Method method : toolBean.getClass().getDeclaredMethods()) {
            AiToolDef toolDef = method.getAnnotation(AiToolDef.class);
            if (toolDef == null) {
                continue;
            }
            ToolMethod toolMethod = ToolMethod.of(objectMapper, toolBean, method, toolDef);
            String toolName = toolMethod.spec().getName();
            assertNameAvailable(toolName);
            methods.put(toolName, toolMethod.withSpec(toolMethod.spec().copy()));
            specs.put(toolName, toolMethod.spec().copy());
        }
    }

    /**
     * 注册只提供目录元数据的 HTTP Tool。HTTP Tool 由 Pi 直接调用 Controller URL，不能进入反射执行入口。
     */
    void registerHttpTool(ToolSpec spec) {
        if (spec == null) {
            return;
        }
        assertNameAvailable(spec.getName());
        specs.put(spec.getName(), spec.copy());
    }

    private void assertNameAvailable(String toolName) {
        if (toolName == null || toolName.isBlank()) {
            throw new IllegalStateException("AI Tool 名称不能为空");
        }
        if (specs.containsKey(toolName)) {
            // 单个 Provider 内重名通常是注解接入错误，必须启动失败；跨 Provider 优先级由 Pi 合并目录时处理。
            throw new IllegalStateException("同一 Tool Provider 存在重名 AI Tool: " + toolName);
        }
    }

    /**
     * 工具统一调用入口，负责将异常归一为稳定错误码
     */
    public ToolResult invoke(String toolName, JsonNode args, AiRunContext ctx) {
        ToolMethod method = methods.get(toolName);
        if (method == null) {
            return ToolResults.fail("tool_not_allowed", "工具不在白名单: " + toolName);
        }
        try {
            Object raw = method.invokeRaw(args == null || args.isNull() ? objectMapperFor(method).createObjectNode() : args, ctx);
            return ToolResults.success(objectMapperFor(method), raw);
        } catch (ToolArgsMissingException e) {
            return ToolResults.fail("tool_args_missing", e.getMessage());
        } catch (ToolArgsInvalidException e) {
            return ToolResults.fail("tool_args_invalid", messageOf(e));
        } catch (ToolExecException e) {
            String code = e.getCode() == null || e.getCode().isBlank() ? "tool_exec_failed" : e.getCode();
            return ToolResults.fail(code, messageOf(e));
        } catch (IllegalArgumentException e) {
            String msg = messageOf(e);
            if (msg.startsWith("缺少必填参数:")) {
                return ToolResults.fail("tool_args_missing", msg);
            }
            return ToolResults.fail("tool_args_invalid", msg);
        } catch (RuntimeException e) {
            throw e;
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }

    private ObjectMapper objectMapperFor(ToolMethod method) {
        return method == null ? new ObjectMapper() : method.objectMapper();
    }

    private String messageOf(Throwable throwable) {
        return throwable == null || throwable.getMessage() == null ? String.valueOf(throwable) : throwable.getMessage();
    }

    /**
     * 返回可用于 tools/list 的工具定义快照
     */
    public List<ToolSpec> listToolSpecs() {
        return new ArrayList<>(specs.values());
    }

    public static final class ToolSpec {
        private String name;
        private String title;
        private String description;
        private List<ToolParamSpec> parameters;
        private ToolResultSpec result;
        private ToolExecutionSpec execution;

        public ToolSpec(String name, String description, List<ToolParamSpec> parameters) {
            this(name, "", description, parameters, null);
        }

        public ToolSpec(String name, String description, List<ToolParamSpec> parameters, ToolResultSpec result) {
            this(name, "", description, parameters, result);
        }

        public ToolSpec(String name, String title, String description,
                        List<ToolParamSpec> parameters, ToolResultSpec result) {
            this(name, title, description, parameters, result, ToolExecutionSpec.local());
        }

        public ToolSpec(String name, String title, String description,
                        List<ToolParamSpec> parameters, ToolResultSpec result, ToolExecutionSpec execution) {
            this.name = name;
            this.title = title;
            this.description = description;
            this.parameters = parameters;
            this.result = result;
            this.execution = execution == null ? ToolExecutionSpec.local() : execution;
        }

        public String getName() {
            return name;
        }

        public void setName(String name) {
            this.name = name;
        }

        public String getTitle() {
            return title;
        }

        public void setTitle(String title) {
            this.title = title;
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

        public List<ToolParamSpec> getParameters() {
            return parameters;
        }

        public void setParameters(List<ToolParamSpec> parameters) {
            this.parameters = parameters;
        }

        public ToolResultSpec getResult() {
            return result;
        }

        public void setResult(ToolResultSpec result) {
            this.result = result;
        }

        public ToolExecutionSpec getExecution() {
            return execution;
        }

        public void setExecution(ToolExecutionSpec execution) {
            this.execution = execution;
        }

        public ToolSpec copy() {
            List<ToolParamSpec> copied = new ArrayList<>();
            if (parameters != null) {
                for (ToolParamSpec parameter : parameters) {
                    copied.add(new ToolParamSpec(
                        parameter.getName(),
                        parameter.getType(),
                        parameter.isRequired(),
                        parameter.getDescription(),
                        parameter.getTitle(),
                        parameter.getExamples(),
                        parameter.getSchema()
                    ));
                }
            }
            ToolResultSpec copiedResult = result == null ? null : result.copy();
            return new ToolSpec(
                name,
                title,
                description,
                copied,
                copiedResult,
                execution == null ? ToolExecutionSpec.local() : execution.copy()
            );
        }
    }

    /** Java tools/list 中稳定的执行路由；HTTP 参数绑定只描述 Controller 已有契约。 */
    public static final class ToolExecutionSpec {
        private String type;
        private String method;
        private String path;
        private List<HttpParamBindingSpec> bindings = new ArrayList<>();

        public static ToolExecutionSpec local() {
            ToolExecutionSpec execution = new ToolExecutionSpec();
            execution.type = "LOCAL";
            return execution;
        }

        public static ToolExecutionSpec http(String method, String path, List<HttpParamBindingSpec> bindings) {
            ToolExecutionSpec execution = new ToolExecutionSpec();
            execution.type = "HTTP";
            execution.method = method;
            execution.path = path;
            if (bindings != null) {
                execution.bindings.addAll(bindings);
            }
            return execution;
        }

        public String getType() {
            return type;
        }

        public String getMethod() {
            return method;
        }

        public String getPath() {
            return path;
        }

        public List<HttpParamBindingSpec> getBindings() {
            return bindings;
        }

        ToolExecutionSpec copy() {
            List<HttpParamBindingSpec> copiedBindings = new ArrayList<>();
            for (HttpParamBindingSpec binding : bindings) {
                copiedBindings.add(binding.copy());
            }
            ToolExecutionSpec copied = new ToolExecutionSpec();
            copied.type = type;
            copied.method = method;
            copied.path = path;
            copied.bindings = copiedBindings;
            return copied;
        }
    }

    /** Tool 参数名与 HTTP Path/Query/Body 的确定性映射。 */
    public static final class HttpParamBindingSpec {
        private final String parameter;
        private final String httpName;
        private final String source;
        private final boolean required;

        public HttpParamBindingSpec(String parameter, String httpName, String source, boolean required) {
            this.parameter = parameter;
            this.httpName = httpName;
            this.source = source;
            this.required = required;
        }

        public String getParameter() {
            return parameter;
        }

        public String getHttpName() {
            return httpName;
        }

        public String getSource() {
            return source;
        }

        public boolean isRequired() {
            return required;
        }

        HttpParamBindingSpec copy() {
            return new HttpParamBindingSpec(parameter, httpName, source, required);
        }
    }

    public static final class ToolResultSpec {
        private String description;
        private Map<String, String> fields = new LinkedHashMap<>();
        private JsonNode schema;

        public ToolResultSpec() {
        }

        public ToolResultSpec(String description, Map<String, String> fields) {
            this.description = description;
            if (fields != null) {
                this.fields.putAll(fields);
            }
        }

        public String getDescription() {
            return description;
        }

        public void setDescription(String description) {
            this.description = description;
        }

