   252										let textNote = `Read image file [${mimeType}]\n${processed.message}`;
   253										if (nonVisionImageNote) textNote += `\n${nonVisionImageNote}`;
   254										content = [{ type: "text", text: textNote }];
   255									} else {
   256										let textNote = `Read image file [${processed.mimeType}]`;
